def check_uniqueness_ap(d_r, d_c):
    """
    Checks if the difference set of an AP of length 7 with common difference d_r
    is disjoint from the difference set of an AP of length 7 with common difference d_c,
    except for zero differences (which are trivial).
    Condition: (i-k)*d_r != (l-j)*d_c for i!=k and l!=j.
    """
    diffs_r = set()
    diffs_c = set()

    N = 7

    # Generate all non-zero differences for R
    for i in range(N):
        for k in range(N):
            if i != k:
                diffs_r.add((i - k) * d_r)

    # Generate all non-zero differences for C
    for l in range(N):
        for j in range(N):
            if l != j:
                diffs_c.add((l - j) * d_c)

    # Check for intersection
    intersection = diffs_r.intersection(diffs_c)

    if not intersection:
        return True
    else:
        # Print the intersection for debugging/reporting
        return False, intersection

solutions = []
for d_r in range(1, 8): # d_r must be positive and less than 8
    d_c = 8 - d_r

    is_unique, intersection = check_uniqueness_ap(d_r, d_c)

    if is_unique:
        solutions.append((d_r, d_c))
    else:
        print(f"Found overlap for (d_r={d_r}, d_c={d_c}): {intersection}")

print("--- Search Results ---")
if solutions:
    for dr, dc in solutions:
        print(f"Solution found: d_R = {dr}, d_C = {dc}")
else:
